typedef float time_value_t;

struct virtual_entry {
    short adjustment;
    short reserved;
    void (*function)();
};

struct FEMenu {
    virtual_entry *vtable;

    void Update(time_value_t time_inc)
    {
        virtual_entry &entry = vtable[11];
        ((void (*)(void *, time_value_t))entry.function)
            ((char *)this + entry.adjustment, time_inc);
    }
};

struct PanelQuad {
    virtual_entry *vtable;

    void Update(time_value_t time_inc)
    {
        virtual_entry &entry = vtable[6];
        ((void (*)(void *, time_value_t))entry.function)
            ((char *)this + entry.adjustment, time_inc);
    }
};

struct FEEntityManager {
    char padding[0x1c0];
    bool cam_stopped;
    char alignment[3];
    int cam_stopped_at;

    bool OKtoDrawSurferSelect()
    {
        return cam_stopped && cam_stopped_at == 1;
    }
};

struct FEManager {
    char padding[0xc];
    FEEntityManager *em;
};

extern "C" void graphical_update(void *, time_value_t)
    __asm__("Update__15FEGraphicalMenuf");
__asm__(".equ Update__15FEGraphicalMenuf, 0x00159DF8");

class FEGraphicalMenu {
    char padding0[0x60];
protected:
    FEMenu *active;
    char padding1[0x100];
public:
    void Update(time_value_t time_inc)
    {
        graphical_update(this, time_inc);
    }
};

class SurferFrontEnd : public FEGraphicalMenu {
    char padding2[0xec];
    PanelQuad *red_gauges[4];
    char padding3[0x48];
    PanelQuad *hcap_color[3];
    void *ents[3];
    FEManager *manager;
    bool wait_for_camera;

public:
    void Update(time_value_t time_inc);
};

void SurferFrontEnd::Update(time_value_t time_inc)
{
	if(active) active->Update(time_inc);
	else
	{
		if(wait_for_camera && manager->em->OKtoDrawSurferSelect()) wait_for_camera = false;
		else if(!wait_for_camera && !manager->em->OKtoDrawSurferSelect()) wait_for_camera = true;
		FEGraphicalMenu::Update(time_inc);
		for(int i=0; i<4; i++)
		{
			red_gauges[i]->Update(time_inc);
			if(i<3) hcap_color[i]->Update(time_inc);
		}
	}
}
